Translate("frFR", "excavation-site", {
	title = "Excavation Site",
	aliases = { "Excavation Site: Wetlands" },
	sections = {
		{
			title = "Résumé",
			text = [=[Haut dans les collines des {link:wetlands}Paluns{/link}, au-dessus du camp en ruine des fouilles de {link:prospector-whelgar}Whelgar{/link}, se trouve un lieu que le temps semble avoir oublié. Depuis quelque temps, une étrange brume descend des montagnes, et des lumières brillent la nuit sur les hauteurs. Un second camp se dresse parmi les rochers, avec des tentes, des caisses et d'énormes crânes cornus à demi enfouis dans le sol, et une grande pierre verte derrière une barricade de bois. Au-delà, sous un grand arbre, une colonne de brume bleue s'ouvre dans le sol. Ce qui attend en dessous est plus ancien que toute forteresse naine.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte qui bâtit les lieux antiques sous les hautes terres, ni quand. Les fouilleurs de la {link:explorers-league}Ligue des explorateurs{/link}, dans le marais en contrebas, ont trouvé de grands ossements et une tablette dans l'écriture des titans, la {link:goaz-stone}Goaz Stone{/link}, qui parle de Dieux très anciens enchaînés sous la terre. Nul érudit n'a encore pu dire si la tablette et les caveaux des hautes terres appartiennent à une même histoire. Ce que l'on sait, c'est que les créations des titans se sont éveillées ici, et qu'elles se sont égarées.]=],
		},
		{
			title = "La descente",
			text = [=[Le chemin vers le bas traverse quatre lieux que les fouilleurs ont nommés. Le Lost Dig Site est ce qui reste d'un camp qui creusa trop profond. Le Stalker's Thicket est un enchevêtrement de végétation où les raptors chassent en meute. Le Lost Marsh est une caverne noyée de roseaux et d'eau noire, où des crânes géants gisent parmi les joncs et où des crocilisques glissent sous la surface. Au bout se trouve le Site of the Guardian, un caveau de grandes pierres travaillées.]=],
		},
		{
			title = "Ceux qui demeurent en dessous",
			text = [=[• {b}{link:saltspine}Saltspine{/link}{/b}, un crocilisque pâle d'un grand âge et d'une grande taille.
• {b}{link:shadetooth}Shadetooth{/link}{/b}, un raptor plus grand que tous ceux du marais d'en haut, à la tête de sa propre meute de chasse.
• {b}La {link:highland-horror}Highland Horror{/link}{/b}, une chose monstrueuse de boue et de pourriture qui surgit de la tourbière.
• {b}Le {link:relic-guardian}Relic Guardian{/link}{/b}, une création de pierre grise qui garde encore le caveau qu'elle fut faite pour garder.]=],
		},
		{
			title = "De nos jours",
			text = [=[La {link:explorers-league}Ligue des explorateurs{/link} a de bonnes raisons de s'intéresser à ce qui se trouve en dessous. Leurs collègues des fouilles de {link:prospector-whelgar}Whelgar{/link} ont déjà payé cher les secrets des {link:wetlands}Paluns{/link}, et les survivants sont toujours pris au piège sur leur promontoire. Les créatures des hautes terres, tortues, araignées et bêtes tapies, se sont enhardies autour du portail.]=],
		},
	},
})

