			text = [=[Saltspine est un crocilisque d'une taille énorme, pâle comme l'os, qui vit dans les eaux sombres sous les hautes terres des {link:wetlands}Paluns{/link}. Le marais d'en haut est plein de crocilisques dont les peaux se vendent dans tous les ports, mais aucun n'est semblable à celui-ci. Il a vieilli et grandi dans un lieu où aucun chasseur n'est venu depuis des âges.]=],
		},
		{
			title = "Non consigné",
			text = [=[Nul ne sait depuis combien de temps Saltspine vit en dessous, ni de quoi il s'est nourri dans l'obscurité. Son nom est tout ce que les fouilleurs lui ont donné.]=],
		},
	},
	bonds = {
		{ id = "shadetooth", name = "Shadetooth", note = "partage les profondeurs avec lui" },
	},
})

