	sections = {
		{
			title = "Résumé",
			text = [=[Shadetooth est un raptor à la peau violette et d'une taille géante qui mène une meute de chasseurs sous les hautes terres des {link:wetlands}Paluns{/link}. Les raptors du fourré guettent, traquent et frappent ensemble, et une grande matriarche court parmi eux. Là-haut dans le marais, les raptors tachetés qui envahirent les fouilles de {link:prospector-whelgar}Whelgar{/link} étaient menés par l'un d'eux, plus grand que les autres. En dessous, c'est Shadetooth que la meute suit.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les raptors des profondeurs sont-ils parents de ceux qui infestent le marais d'en haut ? Nul ne l'a encore appris.]=],
