	sections = {
		{
			title = "Résumé",
			text = [=[La Highland Horror est une créature monstrueuse de boue, d'eau et de végétation pourrissante qui se tapit dans les tourbières sous les hautes terres des {link:wetlands}Paluns{/link}. Elle ressemble par sa forme aux rampants plus petits des profondeurs, mais elle est bien plus grande. Dans le marais d'en haut, le Greenwarden parle de choses fiévreuses qui surgissent d'une plaie purulente de la terre. La Horror semble née de la même maladie, parvenue à une taille qu'aucun marécage ne pourrait contenir.]=],
		},
		{
			title = "Non consigné",
			text = [=[Ce qui appela la Horror hors de la fange, et si elle était là avant que les créations des titans ne s'éveillent, on ne le sait pas.]=],
		},
	},
	bonds = {
		{ id = "relic-guardian", name = "Relic Guardian", note = "garde le caveau au-delà d'elle" },
	},
})

