	sections = {
		{
			title = "Résumé",
			text = [=[Le Relic Guardian est une création de pierre grise qui se dresse dans le caveau le plus profond sous les hautes terres des {link:wetlands}Paluns{/link}, le lieu que les fouilleurs appellent le Site of the Guardian. Il fut fait pour garder quelque chose, et il le garde encore.]=],
		},
		{
			title = "Importance",
			text = [=[Si les créations des titans sont la cause de la brume et des lumières d'en haut, le Gardien est le cœur de l'affaire. Ce qu'il garde est peut-être ce que la {link:explorers-league}Ligue des explorateurs{/link} cherchait.]=],
